// Official numeric records generated by localOfficialUnits; no game art or user installation data in this fixture.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { getData } from '../../server/data.js';
import { applyPatches } from '../../shared/plugins/patch.js';
import { diyRecord } from '../../shared/diy.js';
import { DataSource } from '../../server/sim/simdata.js';
import { makeBattle } from '../helpers/battleHarness.js';

const base = getData();
const fixture = JSON.parse(readFileSync(new URL('../fixtures/optional-recruits.json', import.meta.url), 'utf8'));
const composed = applyPatches(base, fixture.ops, { pluginId: 'collab-recruits' });
assert.deepEqual(composed.problems, []);
const raw = composed.data, data = new DataSource(raw);
const ids = ['char_x_collab_recruits_oblvns', 'char_x_collab_recruits_makoto'];
const enemy = Object.values(raw.enemies).find(e => e.stats?.maxHp > 1000 && e.stats.motion === 'WALK');

test('local recruits add exactly two DIY entries, no bonds or shop chess, and preserve all vanilla operators', () => {
  assert.deepEqual(raw.bonds, base.bonds);
  assert.deepEqual(raw.chess, base.chess);
  assert.deepEqual(raw.backups.diy.ownedPool.filter(id => !base.backups.diy.ownedPool.includes(id)).sort(), [...ids].sort());
  for (const [id, unit] of Object.entries(base.backups.units)) assert.deepEqual(raw.backups.units[id], unit);
});

for (const charId of ids) for (const tier of [5, 6]) for (const elite of [false, true]) for (let skillIndex = 0; skillIndex < 3; skillIndex++) {
  test(`${charId}: tier ${tier}, ${elite ? 'elite' : 'normal'}, skill ${skillIndex + 1} uses its real kit and module`, () => {
    const slot = `chess_char_${tier}_diy1_a`, unit = raw.backups.units[charId];
    const form = unit.forms[elite ? `2/60/7/${tier === 5 ? 1 : 3}` : '2/1/4/0'];
    const uniEquipId = elite ? form.modules[0].uniEquipId : undefined;
    const pick = { charId, skillIndex, ...(uniEquipId ? { uniEquipId } : {}) };
    const rec = diyRecord(slot, pick, { elite, data: raw });
    assert.equal(rec.skill.index, skillIndex);
    assert.equal(rec.module?.level ?? 0, elite ? tier === 5 ? 1 : 3 : 0);
    assert.deepEqual(rec.bonds, charId.endsWith('oblvns') ? ['emptyShip'] : ['lateranoShip']);
    const h = makeBattle({ data, units: [{ diy: { slot, ...pick }, elite, row: 9, col: 5 }],
      enemies: [{ key: enemy.key, pos: [9, 6], mods: { hpMul: 100000, atkMul: 0, speedMul: 0 } }], timeLimit: 75, autoFinish: false });
    h.run(1);
    const u = h.allies().find(u => u.kind === 'op'), target = h.enemies()[0], hp = target.hp;
    if (charId.endsWith('oblvns')) {
      assert.ok(Array.isArray(u.mem.sakikoNotes), 'native projectile kit must run instead of generic fallback');
      h.b._sakikoFever.get(u.ownerId).value = 450;
    }
    u.skill.activate('verification', { free: true });
    h.run(40);
    assert.deepEqual(h.b.errors, []);
    assert.ok(target.hp < hp, 'selected skill must deal damage');
    h.invariants();
  });
}
